#[test]
fn paged_semantic_source_admits_original_owned_custody_and_settles_every_allocation(){
 use semio_framework_value::{NativeEncodeControl,paged_text::{PagedText,TextReadSource},retained_clone::{RetainedCloneSource,RetainedCloneGrant,RetainedCloneStep}};
 use semio_framework_dsl_record::{BorrowedFieldSpec as F,BorrowedRecordSpec as S,BorrowedShape as B,native_encoding::{FieldProjectionSource,FieldProjectionView as V}};
 type Owner=PagedText<8194>;type Source=RetainedCloneSource<Owner>;
 struct Original;impl TextReadSource for Original{fn byte_len(&self)->usize{8194}fn byte_at(&self,index:usize)->Option<u8>{(index<8194).then_some(b'x')}}
 struct Borrowed<'a>(&'a Owner);impl FieldProjectionSource for Borrowed<'_>{fn projection_view(&self,path:&[usize])->Result<V<'_>,ValueError>{match path{[]=>Ok(V::Record(&[0])),[0]=>Ok(V::TextSource(self.0.read_view()?)),_=>Err(semio_framework_dsl_record::native_encoding::projection_path_error())}}}
 static FIELDS:[F;1]=[F::new(0,"value",B::Text)];
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔗️paged-source-custody/🔣️.json")).unwrap();assert_eq!(fixture["sourceBytes"],8194);assert_eq!(fixture["bodyBytes"],8200);assert_eq!(fixture["metadataWindowBytes"],512);assert_eq!(fixture["maximumAllocationBytes"],65536);assert_eq!(fixture["maximumCapacityBytes"],4096);assert_eq!(fixture["maximumReleaseBytes"],4096);
 let mut owner=Owner::empty();let mut allow=|_|true;let mut control=NativeEncodeControl::new(65536,&mut allow);let(result,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.read_from_encoding_source(&Original,&mut control));result.unwrap();assert!(!event.overflowed);assert_eq!(event.released_bytes,0);let backing=owner.allocated_bytes();assert_eq!(event.requested_bytes,backing);assert_eq!(control.owned_bytes(),backing);let birth=Source::owned_constructor_capacity_bytes::<()>();assert!(birth>0&&birth<=4096);
 for denied in fixture["constructorDenials"].as_array().unwrap().iter().map(|denied|denied.as_str().unwrap()){let grant=RetainedCloneGrant{maximum_items:usize::from(denied!="zero-items"),maximum_capacity_bytes:if denied=="one-short-capacity"{birth-1}else{birth},maximum_depth:usize::from(denied!="zero-depth"),..Default::default()};let(result,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||Source::admit_owned(owner,(),grant));let(error,returned,_)=match result{Err(refused)=>refused,Ok(_)=>panic!("original source custody constructor must retain denied input")};assert!(matches!(error.kind,semio_framework_value::ValueRefusalKind::WorkLimit|semio_framework_value::ValueRefusalKind::OwnershipLimit|semio_framework_value::ValueRefusalKind::DepthLimit));assert_eq!((event.requested_bytes,event.released_bytes),(0,0));assert_eq!(returned.allocated_bytes(),backing);assert_eq!(returned.read_view().unwrap().len(),8194);owner=returned;}
 control.charge(birth).unwrap();let(result,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||Source::admit_owned(owner,(),RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:birth,maximum_depth:1,..Default::default()}));let(mut source,progress)=result.unwrap_or_else(|(error,_,_)|panic!("admitted original source refused: {error}"));assert!(!event.overflowed);assert_eq!((event.requested_bytes,event.released_bytes),(birth,0));assert_eq!(progress.retained_capacity_bytes,birth);assert_eq!(control.owned_bytes(),backing+birth);
 {let borrowed=source.borrow();let original=borrowed.get();assert_eq!(original.allocated_bytes(),backing);let projected=Borrowed(original);let mut capsule=super::BorrowedProjectedPackOperation::from_source(&projected,S{keyword:None,layout:RecordLayout::Inline,fields:&FIELDS});let mut measurement=protocol::io::binary::operation_bytes::OperationByteMeasurement::new(8200);let window=control.owned_bytes()+512;let(result,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||control.scoped_maximum(window,|control|capsule.write_body(&EncodeOptions::default(),&mut measurement,control)));assert_eq!(result.unwrap(),8200);assert_eq!((event.requested_bytes,event.released_bytes),(0,0));assert_eq!(original.allocated_bytes(),backing);for index in 0..8194{assert_eq!(original.read_view().unwrap().byte_at(index),Some(b'x'));}let scratch=capsule.allocated_bytes();let mut disposed=0;for _ in 0..32768{let(step,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||capsule.retire_one(1,4096).unwrap());assert_eq!(event.requested_bytes,0);assert_eq!(event.released_bytes,step.2);assert!(step.1<=1&&event.released_bytes<=4096&&event.largest_release_bytes<=4096);disposed+=event.released_bytes;if !step.0{break}}assert_eq!(disposed,scratch);}
 let(step,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.close_step(Default::default()).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((event.requested_bytes,event.released_bytes),(0,0));let(mut born,mut disposed,mut copied)=(0,0,0);
 for _ in 0..100000{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:64};let(step,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.close_step(grant).unwrap());let progress=match step{RetainedCloneStep::Progress(progress)|RetainedCloneStep::Complete(progress)=>progress};assert!(progress.fits(grant));assert!(!event.overflowed);assert_eq!(event.requested_bytes,progress.retained_capacity_bytes);assert_eq!(event.released_bytes,progress.released_bytes);assert!(event.requested_bytes<=4096&&event.released_bytes<=4096&&event.largest_release_bytes<=4096);born+=event.requested_bytes;disposed+=event.released_bytes;copied+=progress.copied_bytes;if source.terminal_is_empty(){break}}
 assert!(source.terminal_is_empty());assert_eq!(disposed,backing+birth+born);assert!(copied>=8194);assert_eq!(source.next_close_copy_byte_demand().unwrap(),0);assert_eq!(source.next_close_release_byte_demand().unwrap(),0);assert_eq!(source.next_close_depth_demand().unwrap(),0);let(_,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(source));assert_eq!((event.requested_bytes,event.released_bytes),(0,0));eprintln!("[DEBUG] actual typed paged source original8194 backing={backing} custodyBirth={birth} closeBirth={born} disposed={disposed} copied={copied}; single cumulative65536 and positive metadata512; all original/custody/scaffold events fit independent1/4096 grants; authored whole carrier separate");
}
